// Image reconstruction kernel module
kernel img_rec_km[IMG_SOLVERS_PER_SWITCH];


//***** PACKET SWITCHING OBJECTS *****//
pktsplit<IMG_SOLVERS_PER_SWITCH> sp;
pktmerge<IMG_SOLVERS_PER_SWITCH> mg;


//***** GMIO PORT OBJECTS *****//

